// usage: node chk.mjs tsconfig file.tsx [prop]  -> the TypeScript checker's type for each own prop (apps/oracle's typescript)
import ts from '/tmp/claude-501/rdtdiff/apps/oracle/node_modules/typescript/lib/typescript.js'
const [tsconfig, file, only] = process.argv.slice(2)
const dir = tsconfig.replace(/\/[^/]*$/, '')
const cfg = ts.parseJsonConfigFileContent(ts.readConfigFile(tsconfig, ts.sys.readFile).config, ts.sys, dir)
const p = ts.createProgram([file], cfg.options)
const c = p.getTypeChecker()
const sf = p.getSourceFile(file)
const sym = c.getSymbolAtLocation(sf)
console.log('typescript', ts.version)
for (const e of c.getExportsOfModule(sym)) {
  const t = c.getTypeOfSymbolAtLocation(e, sf)
  const sig = t.getCallSignatures()[0]
  if (!sig) continue
  const pt = c.getTypeOfSymbolAtLocation(sig.parameters[0], sf)
  console.log(e.name)
  for (const pr of c.getPropertiesOfType(pt)) {
    const inReact = pr.declarations?.some((d) => d.getSourceFile().fileName.includes('@types/react'))
    if (!only && inReact) continue
    if (only && pr.name !== only) continue
    console.log('  ', pr.name, ':', c.typeToString(c.getTypeOfSymbolAtLocation(pr, sf), undefined, ts.TypeFormatFlags.NoTruncation | ts.TypeFormatFlags.InTypeAlias))
  }
}

