"""usage: cal2.py srcdir prop -> caliper's type for one prop (all components in srcdir), weekly oracle flags"""
import json, subprocess, sys
b = '/tmp/claude-501/rdtdiff/target/release/caliper-docgen'
out = subprocess.run([b, 'extract', '--src', sys.argv[1], '--json', '--html-attributes', 'full', '--include-unexported',
                      '--load-dependencies', '--collapse-inherited-props', 'none', '--quiet'], capture_output=True, text=True)
j = json.loads(out.stdout)
for k, c in j['components'].items():
    props = c['props']
    if isinstance(props, list):
        m = {}
        for i in props:
            m.update(j['propSets'][i])
        props = m
    print(c['displayName'], 'lists', len(props), 'props;', sys.argv[2], 'listed:', sys.argv[2] in props)
    if sys.argv[2] in props:
        print('  ', json.dumps(j['props'][props[sys.argv[2]]]['type']))

